{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C50","C52","C58","C59","C60","C62","C64","C65","C67","C70"],
  "contradictory_card_ids": ["C06","C13","C16","C32","C33"],
  "prediction_basis_card_ids": ["C50","C52","C58","C60","C62","C64","C65","C59"],
  "claims": [
    {
      "claim": "The query is 5-azacytidine, a highly polar ribonucleoside (logD -3.17, TPSA 143.7); L4 Caco-2 records for levovirin (0.12×10^-6 cm/s) and gemcitabine (<1×10^-6 and 0.99×10^-6 cm/s) show low passive permeability for polar ribonucleoside/cytidine analogs.",
      "card_ids": ["C50","C52","C58"]
    },
    {
      "claim": "L5 Caco-2/MDCK records extend this pattern: EFdA A→B Papp ~4-6×10^-7 cm/s (C60, C64) and GS-441524 A→B Papp 0.229×10^-6 cm/s with BCRP/MDR1 efflux (C62, C65, C67, C70) indicate low permeability plus efflux for other nucleoside analogs.",
      "card_ids": ["C60","C62","C64","C65","C67","C70"]
    },
    {
      "claim": "L5 efflux experiments show cladribine is a BCRP substrate (efflux ratio reduced to 1.09 with Ko143; C59/C68/C69), supporting gut-wall efflux as a plausible presystemic loss mechanism for polar nucleosides.",
      "card_ids": ["C59","C68","C69"]
    },
    {
      "claim": "L5 transporter-uptake records for gemcitabine (C61) and NHC (C66) show some cytidine-like nucleosides are substrates of intestinal nucleoside transporters; this could partially mitigate low passive permeability, but no F outcome is attached and it does not affirmatively establish F>=20.",
      "card_ids": ["C61","C66"]
    },
    {
      "claim": "Direct high-F records for emtricitabine (92%, C16/C33) and didanosine (30-54%, C13/C32) are gold outcomes for other nucleoside scaffolds (oxathiolane/dideoxy) and are less transferable to the ribonucleoside query; acyclovir's 20% (C06) is at the threshold and does not affirmatively support F>=20.",
      "card_ids": ["C06","C13","C16","C32","C33"]
    },
    {
      "claim": "L3 lamivudine exposure records (C40, C44) demonstrate rapid absorption and measurable AUC after oral dosing, but they are exposure endpoints without F and use an oxathiolane nucleoside scaffold, so they do not provide affirmative F>=20 evidence for the ribonucleoside query.",
      "card_ids": ["C40","C44"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C59","C60","C62","C64","C65","C67","C68","C69","C70"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for 5-azacytidine is present in the supplied records.",
    "No query-specific Caco-2/MDCK permeability, efflux, or intestinal metabolism data; all L4/L5 records are for analog nucleosides with inferred transferability.",
    "Cytidine deaminase-mediated first-pass metabolism and gut-wall metabolism for the query are not directly measured.",
    "Possible CNT/ENT transporter-mediated uptake for the query is not directly measured; L5 substrate records for gemcitabine/NHC are analog evidence only.",
    "The query_prior reasoning text names guanosine, but the canonical SMILES corresponds to 5-azacytidine; the prior is treated only as an uncertain physicochemical prior.",
    "High-F records for emtricitabine/didanosine come from different nucleoside scaffolds; their transferability to the ribonucleoside query is limited."
  ],
  "decision_summary": "Prediction remains low and is strengthened by L5: low Caco-2/MDCK permeability for EFdA and GS-441524 plus BCRP/MDR1 efflux for cladribine/GS-441524 reinforce the L4 low-permeability evidence for polar ribonucleoside/cytidine analogs; transporter-uptake records for gemcitabine/NHC do not establish F>=20, and no direct F for 5-azacytidine is available."
}

